arguments.new_string:
def __init__(self, method_name, *args, **kwargs):
    self.method_name = method_name
    if args:
        # First positional arg could be either the args tuple or individual args
        # For compatibility, treat it as args tuple if it's a tuple/list
        if len(args) == 1 and isinstance(args[0], (tuple, list)):
            self.args = tuple(args[0])
        else:
            self.args = args
    else:
        self.args = ()
    self.kwargs = kwargs

